{
  "event_id": "E039",
  "summary": "A moderate geomagnetic storm occurred from September 27 to September 29, 2017, with aDst minimum of -98 nT. The storm was associated with sustained southward Bz, fast solar wind, and a southward Bz of -10.6 nT for 8 hours, consistent with geomagnetic storm conditions.",
  "characteristics": [
    {
      "statement": "Dst minimum of -98 nT.",
      "evidence": ["dst.min_nT"]
    },
    {
      "statement": "Sustained southward Bz of -10.6 nT for 8 hours.",
      "evidence": ["drivers.bz_min_hourly_nT", "drivers.bz_min_time"]
    },
    {
      "statement": "Fast solar wind with a maximum speed of 713 km/s.",
      "evidence": ["drivers.speed_max_km_per_s"]
    }
  ],
  "possible_physical_interpretation": [
    {
      "statement": "Southward Bz is the main way solar wind energy enters the magnetosphere, causing geomagnetic storms.",
      "sources": ["d03_c000", "d03_c001"]
    }
  ],
  "potential_impacts": [],
  "caveats": [
    "All values are hourly means in UTC; minute-level extremes are larger.",
    "Solar wind and magnetic field values are shifted to the time they reach Earth (a delay of roughly 25 to 100 minutes depending on solar wind speed).",
    "Bz is in GSM coordinates; negative Bz means southward.",
    "Dst minimum is final."
  ],
  "unsupported_or_unknown": [
    "physical cause of the event: no supporting source",
    "impacts on satellites, GNSS, radio communication, power grids or aurora: no supporting source",
    "comparison with, or ranking against, other historical storms: no supporting source",
    "any forecast or prediction: no supporting source"
  ]
}
